import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Ring 3 and the syscall surface","description":"","frontmatter":{},"headers":[],"relativePath":"arch/syscall-ring3.md","filePath":"arch/syscall-ring3.md"}'),s={name:"arch/syscall-ring3.md"};function c(a,t,i,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="ring-3-and-the-syscall-surface" tabindex="-1">Ring 3 and the syscall surface <a class="header-anchor" href="#ring-3-and-the-syscall-surface" aria-label="Permalink to &quot;Ring 3 and the syscall surface&quot;">​</a></h1><p>How user code reaches the kernel: one instruction (<code>int 0x80</code>), 54 syscall numbers, one 5-argument service door (<code>SYS_L1SVC</code>), and the output-capture mechanism that makes 208 service operations return text. The ABI contract is mirrored in <code>ocos/interface/</code> (<a href="./private-headers.html">private-headers.md</a>); the process/ELF side lives in <code>ocos/kernel/core_usermode.c</code> (1518 lines).</p><h2 id="the-entry-path" tabindex="-1">The entry path <a class="header-anchor" href="#the-entry-path" aria-label="Permalink to &quot;The entry path&quot;">​</a></h2><p>Ring 3 executes <code>int 0x80</code>. The IDT gate for vector 128 carries flags <strong>0xEE (DPL=3)</strong> so the instruction is legal from user mode (selector 0x18, interrupt gate - interrupts off during the handler). The chain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int 0x80</span></span>
<span class="line"><span>  -&gt; arch_isr_stub_128        (pushes fake error code + vector number)</span></span>
<span class="line"><span>  -&gt; arch_isr_common          (pushes 15 GPRs, cld, 16-byte align)</span></span>
<span class="line"><span>  -&gt; arch_isr_dispatch        (frame = 22 u64s, arch_irq_frame_t)</span></span>
<span class="line"><span>  -&gt; core_syscall_dispatch((u64*)frame)     [core_usermode.c]</span></span></code></pre></div><p><strong>ABI</strong>: <code>rax</code> = syscall number; arguments in <code>rdi, rsi, rdx, r10</code> (4th) and <strong><code>r8</code> (5th)</strong>; return in <code>rax</code>; unknown or unregistered numbers return -1. The 5th-argument slot is used by exactly one syscall - <code>SYS_L1SVC</code>&#39;s <code>cap</code> - and is stashed in <code>g_syscall_arg5</code> before the handler runs (frame slot <code>regs[7]</code>; <code>regs[5]</code> is r10). There is no <code>sysenter</code>/<code>syscall</code>-instruction fast path - int 0x80 only - and no per-task nesting: syscalls never recurse in one task. Signal delivery happens after the handler returns, before <code>iretq</code>.</p><p>Registration: <code>core_syscall_register(num, handler)</code> into <code>g_syscalls[256]</code>; <code>usermode_init()</code> seeds 0/1/2 then calls <code>core_syscall_wp08a_init()</code> + <code>core_syscall_wp08fix1_init()</code> + <code>core_syscall_l1svc_init()</code> (the bodies live in <code>ocos/services/sysapi/src/svc_sysapi_syscall.c</code>).</p><h2 id="the-complete-syscall-table-54-numbers" tabindex="-1">The complete syscall table (54 numbers) <a class="header-anchor" href="#the-complete-syscall-table-54-numbers" aria-label="Permalink to &quot;The complete syscall table (54 numbers)&quot;">​</a></h2><p>From <code>ocos/services/sysapi/interface/svc_sysapi_syscall.h</code>:</p><table tabindex="0"><thead><tr><th>#</th><th>Name</th><th>Purpose</th></tr></thead><tbody><tr><td>0</td><td><code>SYS_EXIT</code></td><td>legacy exit (now runs the unified reaper too)</td></tr><tr><td>1</td><td><code>SYS_WRITE</code></td><td>console write with per-page mapping check</td></tr><tr><td>2</td><td><code>SYS_WRITE_AND_EXIT</code></td><td>write then exit</td></tr><tr><td>3</td><td><code>SYS_OPEN</code></td><td>(path, flags)</td></tr><tr><td>4</td><td><code>SYS_CLOSE</code></td><td>(fd)</td></tr><tr><td>5</td><td><code>SYS_STAT</code></td><td>(path, struct ush_stat*)</td></tr><tr><td>6</td><td><code>SYS_READDIR</code></td><td>(path, idx, buf)</td></tr><tr><td>7</td><td><code>SYS_MKDIR</code></td><td>(path)</td></tr><tr><td>8</td><td><code>SYS_RMDIR</code></td><td>(path)</td></tr><tr><td>9</td><td><code>SYS_UNLINK</code></td><td>(path)</td></tr><tr><td>10</td><td><code>SYS_FORK</code></td><td>full frame save + address-space copy + fork-child path</td></tr><tr><td>11</td><td><code>SYS_EXECVE</code></td><td>(name/argv) - gzip registry lookup + ELF load</td></tr><tr><td>12</td><td><code>SYS_WAIT4</code></td><td>(pid, &amp;status)</td></tr><tr><td>13</td><td><code>SYS_KILL</code></td><td>(pid, sig) - guarded procs refuse every signal</td></tr><tr><td>14</td><td><code>SYS_GETPID</code></td><td></td></tr><tr><td>15</td><td><code>SYS_GETPPID</code></td><td></td></tr><tr><td>16</td><td><code>SYS_EXIT2</code></td><td>modern exit (crt0 uses this)</td></tr><tr><td>20</td><td><code>SYS_PIPE</code></td><td>(int pipefd[2])</td></tr><tr><td>30</td><td><code>SYS_MMAP</code></td><td>per-process anonymous bump allocator in [0x3C000000, 0x3FFF0000)</td></tr><tr><td>31</td><td><code>SYS_MUNMAP</code></td><td>(addr, len)</td></tr><tr><td>32</td><td><code>SYS_MPROTECT</code></td><td>(addr, len, prot) - W^X for ld.so</td></tr><tr><td>33</td><td><code>SYS_BRK</code></td><td>(addr)</td></tr><tr><td>40</td><td><code>SYS_SIGNAL</code></td><td>(sig, handler)</td></tr><tr><td>41</td><td><code>SYS_SIGACTION</code></td><td>(sig, act)</td></tr><tr><td>42</td><td><code>SYS_SIGRETURN</code></td><td>restores the saved 22-u64 signal frame</td></tr><tr><td>50</td><td><code>SYS_DUP</code></td><td>(fd)</td></tr><tr><td>51</td><td><code>SYS_DUP2</code></td><td>(oldfd, newfd)</td></tr><tr><td>60</td><td><code>SYS_CHDIR</code></td><td>per-process cwd</td></tr><tr><td>61</td><td><code>SYS_GETCWD</code></td><td></td></tr><tr><td>62</td><td><code>SYS_IOCTL</code></td><td></td></tr><tr><td>70</td><td><code>SYS_READ</code></td><td>(fd, buf, len)</td></tr><tr><td>72</td><td><code>SYS_WRITE2</code></td><td>fd-aware write (pipes/redirect)</td></tr><tr><td>73</td><td><code>SYS_READLINE</code></td><td>kernel line editor</td></tr><tr><td>74</td><td><code>SYS_GETCH</code></td><td>raw key, no echo, non-blocking poll</td></tr><tr><td>75</td><td><code>SYS_UPTIME</code></td><td>ms since boot</td></tr><tr><td>76</td><td><code>SYS_MEMINFO</code></td><td>fills 3 u64 (total/used/free) from PMM</td></tr><tr><td>80</td><td><code>SYS_SELECT</code></td><td></td></tr><tr><td>81</td><td><code>SYS_POLL</code></td><td></td></tr><tr><td>90</td><td><code>SYS_MAP_SOLIB</code></td><td>dlopen kernel side (WP-08b)</td></tr><tr><td>96</td><td><code>SYS_SYMLINK</code></td><td>(target, linkpath)</td></tr><tr><td>97</td><td><code>SYS_READLINK</code></td><td></td></tr><tr><td>98</td><td><code>SYS_LINK</code></td><td>hard link</td></tr><tr><td>99</td><td><code>SYS_CHMOD</code></td><td></td></tr><tr><td>100</td><td><code>SYS_CHOWN</code></td><td></td></tr><tr><td>101</td><td><code>SYS_NETCMD</code></td><td>(op, arg, out, cap); ops: IFCONFIG=1 PING=2 NETSTAT=3 WGET=4</td></tr><tr><td>102</td><td><code>SYS_PS</code></td><td>(buf, cap) -&gt; struct ush_ps_entry[]</td></tr><tr><td>103</td><td><code>SYS_SOCKET</code></td><td>(type SOCK_TCP=1/SOCK_UDP=2)</td></tr><tr><td>104</td><td><code>SYS_NETBIND</code></td><td></td></tr><tr><td>105</td><td><code>SYS_NETCONNECT</code></td><td></td></tr><tr><td>106</td><td><code>SYS_NETACCEPT</code></td><td></td></tr><tr><td>107</td><td><code>SYS_NETSEND</code></td><td></td></tr><tr><td>108</td><td><code>SYS_NETRECV</code></td><td></td></tr><tr><td>109</td><td><code>SYS_NETCLOSE</code></td><td></td></tr><tr><td>110</td><td><code>SYS_L1SVC</code></td><td>(cat, op, arg, out, cap) - the service door</td></tr></tbody></table><p>The socket syscalls take <strong>net socket ids, not process fds</strong> - they do not participate in dup/select/poll/fork (documented in <code>services/ipc</code>); the NETCMD bridge keeps the historical ush built-ins (ifconfig/ping/netstat/wget) on the same captured bodies.</p><h2 id="sys-l1svc-the-single-service-door" tabindex="-1">SYS_L1SVC - the single service door <a class="header-anchor" href="#sys-l1svc-the-single-service-door" aria-label="Permalink to &quot;SYS_L1SVC - the single service door&quot;">​</a></h2><p><code>sys_l1svc(cat, op, arg, out)</code> with <code>cap = core_syscall_arg5()</code> (the r8 slot), implemented in <code>svc_sysapi_syscall.c</code>:</p><ul><li><code>out == 0 &amp;&amp; cap == 0</code> is the OCIRE fire-and-forget spelling -&gt; renders into a 256-byte kernel scratch buffer, copy-back skipped.</li><li><code>cap</code> must be 1..32768 (raised from 8192 in WP06g2 so the bilingual registry listing fits); <code>out</code> is validated by <code>valid_user_ptr</code>.</li><li><code>arg</code> is copied into a 256-byte kernel buffer - <strong>except cat OCIRE (18), which gets a dedicated 4096-byte stack buffer</strong> for the log agent&#39;s appends.</li><li>Before dispatch: <code>sti</code> ... <code>svc_framework_dispatch(...)</code> ... <code>cli</code> - device-wait loops inside op bodies are tick-driven, not dead spins.</li><li>A service&#39;s non-zero exit status is still a successful call; only an unrouteable category/op (or empty out with rc&lt;0) returns -1. Everything else copies the NUL-terminated text back and returns 0.</li></ul><p>Routing is by category string against the <code>.oc_svcs</code> table (the linker-section registry - <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>). <strong>20 categories, 208 ops</strong>, numbering append-only, mirrored byte-for-byte into ring 3 via <code>tools/gen_l1svc_ops.py</code>:</p><table tabindex="0"><thead><tr><th>Cat</th><th>Name</th><th>Folder</th><th>Ops</th><th>Cat</th><th>Name</th><th>Folder</th><th>Ops</th></tr></thead><tbody><tr><td>1</td><td>time</td><td>services/time</td><td>4</td><td>11</td><td>watchdog</td><td>services/watchdog</td><td>1</td></tr><tr><td>2</td><td>block</td><td>services/block</td><td>23</td><td>12</td><td>crypto</td><td>services/crypto</td><td>2</td></tr><tr><td>3</td><td>nic</td><td>services/net</td><td>20</td><td>13</td><td>l1</td><td>services/l1</td><td>3</td></tr><tr><td>4</td><td>snd</td><td>services/audio</td><td>17</td><td>14</td><td>display</td><td>services/display</td><td>17</td></tr><tr><td>5</td><td>power</td><td>services/power</td><td>8</td><td>15</td><td>input</td><td>services/display</td><td>2</td></tr><tr><td>6</td><td>ota</td><td>services/selfhost</td><td>16</td><td>16</td><td>camera</td><td>services/camera</td><td>10</td></tr><tr><td>7</td><td>fs</td><td>services/fs</td><td>6</td><td>17</td><td>usb</td><td>services/usb</td><td>9</td></tr><tr><td>8</td><td>net</td><td>services/net</td><td>14</td><td>18</td><td>ocire</td><td>services/ocembed</td><td>2</td></tr><tr><td>9</td><td>health</td><td>services/health</td><td>3</td><td>19</td><td>diag</td><td>services/diag</td><td>39</td></tr><tr><td>10</td><td>klog</td><td>services/klog</td><td>3</td><td>20</td><td>tui</td><td>services/tui</td><td>9</td></tr></tbody></table><p>Cat 18 is the guard-only OCIRE channel (ops 4 LOG_APPEND / 5 KLOG_SNAPSHOT) - frozen ABI against <code>ocire/agent/ocire_agent.c</code>, refused for every non-guarded caller (<a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>).</p><h2 id="output-capture-why-old-command-bodies-still-work" tabindex="-1">Output capture - why old command bodies still work <a class="header-anchor" href="#output-capture-why-old-command-bodies-still-work" aria-label="Permalink to &quot;Output capture - why old command bodies still work&quot;">​</a></h2><p>Most op bodies are the v1/v2.2.0 shell command bodies that print via <code>screen_console_puts</code>. To serve them through L1SVC, dispatch wraps them in <code>core_kcap_run_fn(fn, arg, out, cap)</code> (<code>ocos/kernel/core_kcap.c</code>): while a capture is active, <strong>the capture hook IS the console hook</strong> (the console driver holds exactly one hook slot), collecting characters into the caller&#39;s buffer and suppressing both the framebuffer draw and the serial tee. Captures stack to 4 levels; only the innermost active capture accepts data; the base hook (the serial-encoder tee) is reinstalled when the last capture ends; overflow is marked, never silently truncated.</p><p>Three routing styles per op (documented in the l1 files):</p><ol><li><strong>captured</strong> - one-shot text ops (the majority).</li><li><strong>direct</strong> - <code>out[0]=0; return fn(arg);</code> for live console sessions: <code>sshd</code>, all 9 TUI ops (<a href="./tui-engine.html">tui-engine.md</a>), <code>ime -i</code>, and <code>power sleep</code> (a captured multi-second park would swallow every console line printed meanwhile - found live during a supervised boot).</li><li><strong>buffer-render</strong> - the service writes into <code>out</code> with its own <code>put()</code> helpers (<code>l1</code>, <code>klog</code>, <code>health</code>, <code>diag</code>, <code>fs</code>, <code>time</code>, <code>watchdog</code> dispatchers).</li></ol><h2 id="processes-elf-and-the-ring-3-world" tabindex="-1">Processes, ELF, and the ring-3 world <a class="header-anchor" href="#processes-elf-and-the-ring-3-world" aria-label="Permalink to &quot;Processes, ELF, and the ring-3 world&quot;">​</a></h2><ul><li><strong>Entry</strong>: <code>execve</code> leaves <code>[rsp]=argc, [rsp+8]=argv</code>; every app links <code>ocos/interface/l1_crt_entry.asm</code> which reads them safely and calls <code>app_main(argc, argv)</code>, exiting via <code>SYS_EXIT2</code>.</li><li><strong>ELF loading</strong>: static ET_EXEC and ET_DYN (PIE) with ASLR, plus the dynamic path - PT_INTERP detection, ld.so mapped at 0x10000000, <code>.dynamic</code>/GOT/PLT relocation by the user-space ld.so, DT_NEEDED resolution against the embedded solib table (<a href="./../l1/solib-loader.html">../l1/solib-loader.md</a>).</li><li><strong>Program registry</strong>: <code>core_userprog_lookup(name, &amp;size)</code> finds one of the 284 gzip-embedded programs (<a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>); <code>SYS_EXECVE</code> inflates on first use.</li><li><strong>Signals</strong>: SIGHUP 1, SIGINT 2, SIGQUIT 3, SIGKILL 9, SIGUSR1 10, SIGSEGV 11, SIGUSR2 12, SIGTERM 15, SIGCHLD 17, NSIG 32; pending delivery on syscall return; SIGSEGV delivery from ring-3 exceptions with a 3-delivery ping-pong guard, then kill (<a href="./interrupts.html">interrupts.md</a>).</li><li><strong>Pipes</strong> (kernel-side): 32 pipes, 4096-byte buffers, fd kinds in <code>user_proc_t.fds[]</code> (0=free, 1=VFS fd, 2=pipe-read, 3=pipe-write), per-end wait queues; <code>pipe_close_fd</code> is exported for the unified reaper.</li><li><strong>mmap</strong>: a per-process anonymous bump allocator in [0x3C000000, 0x3FFF0000) with a 16-region ownership table - no shared memory syscall; fork is an eager copy (<code>VMM_FLAG_COW</code> is defined but unused).</li><li><strong>Job control</strong> (services/ipc): <code>job_create</code> spawns the named embedded program and binds the job to the actual pid (no &quot;highest live pid&quot; guessing - BUG-0249); <code>job_control</code> 0=fg wait, 1=bg, 2=kill via the unified reaper.</li></ul><p>The L1 developer view of everything above: <a href="./../l1/overview.html">../l1/overview.md</a> and <a href="./../l1/surface-map.html">../l1/surface-map.md</a>.</p>`,24)])])}const g=e(s,[["render",c]]);export{u as __pageData,g as default};
